CREATE OR REPLACE FUNCTION public.finance_booking_payment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  total_paid numeric;
BEGIN
  IF NEW.status <> 'booking' THEN
    RETURN NEW;
  END IF;

  IF NEW.price_snapshot IS NULL OR NEW.price_snapshot <= 0 THEN
    RAISE EXCEPTION 'Booking wajib memiliki tagihan valid';
  END IF;

  -- Legacy bookings created before the snapshot column existed are not
  -- retroactively reinterpreted by a later Owner setting change.
  IF NEW.minimum_dp_amount_snapshot IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(SUM(p.amount), 0)
  INTO total_paid
  FROM public.payments p
  WHERE p.transaction_id = NEW.id;

  IF total_paid < NEW.minimum_dp_amount_snapshot THEN
    RAISE EXCEPTION 'Booking wajib memiliki DP minimum sesuai snapshot transaksi';
  END IF;

  IF total_paid > NEW.price_snapshot THEN
    RAISE EXCEPTION 'Total pembayaran melebihi tagihan transaksi';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.finance_snapshot_booking_dp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  setting_row public.finance_settings;
  raw_minimum numeric;
BEGIN
  IF NEW.status <> 'booking' OR NEW.minimum_dp_mode_snapshot IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT * INTO setting_row
  FROM public.finance_settings
  WHERE id = true;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  NEW.minimum_dp_mode_snapshot := setting_row.minimum_dp_mode;
  NEW.minimum_dp_value_snapshot := setting_row.minimum_dp_value;

  raw_minimum := CASE setting_row.minimum_dp_mode
    WHEN 'PERCENTAGE' THEN COALESCE(NEW.price_snapshot, 0) * setting_row.minimum_dp_value / 100
    ELSE setting_row.minimum_dp_value
  END;

  -- Payment storage is numeric(12,2); the Owner rule requires a whole-rupiah
  -- ceiling, so no rounding to thousands is performed.
  NEW.minimum_dp_amount_snapshot := CEIL(raw_minimum);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.finance_training_audit_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  assignment_id_value uuid;
  session_id_value uuid;
  payload jsonb := to_jsonb(NEW);
  transaction_id_value uuid;
  payment_id_value uuid;
  supervisor_id_value uuid;
BEGIN
  IF NOT public.finance_training_context_valid(auth.uid()) THEN
    RETURN NEW;
  END IF;

  session_id_value := COALESCE(
    NULLIF(payload->>'cash_session_id', '')::uuid,
    NULLIF(payload->>'session_id', '')::uuid,
    NULLIF(current_setting('app.finance_training_session_id', true), '')::uuid
  );

  assignment_id_value := public.finance_training_context_assignment(
    auth.uid(), session_id_value
  );

  SELECT s.opened_by
  INTO supervisor_id_value
  FROM public.finance_cash_sessions s
  WHERE s.id = session_id_value
    AND s.status = 'OPEN'
    AND public.finance_training_context_matches_session(auth.uid(), s.id);

  IF assignment_id_value IS NULL OR supervisor_id_value IS NULL THEN
    RAISE EXCEPTION 'Konteks audit Training tidak lengkap';
  END IF;

  transaction_id_value := CASE
    WHEN TG_TABLE_NAME = 'transactions' THEN (payload->>'id')::uuid
    ELSE NULLIF(payload->>'transaction_id', '')::uuid
  END;
  payment_id_value := CASE
    WHEN TG_TABLE_NAME = 'payments' THEN (payload->>'id')::uuid
    ELSE NULL
  END;

  INSERT INTO public.finance_training_audit (
    assignment_id, action, entity_type, entity_id,
    transaction_id, payment_id, session_id,
    operator_id, supervisor_id, details
  )
  VALUES (
    assignment_id_value, TG_OP, TG_TABLE_NAME, (payload->>'id')::uuid,
    transaction_id_value, payment_id_value, session_id_value,
    auth.uid(), supervisor_id_value,
    jsonb_build_object('label', 'Training', 'table', TG_TABLE_NAME)
  );

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.finance_training_transaction_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.finance_training_is_restricted(auth.uid())
     AND NOT public.finance_training_context_valid(auth.uid()) THEN
    RAISE EXCEPTION 'Peserta Training wajib memakai wrapper transaksi dengan sesi kas penanggung jawab';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

